const listReposNeedingReindex = `-- name: ListReposNeedingReindex :many
SELECT id, name, default_branch, default_branch_oid
FROM repos
WHERE deleted_at IS NULL
  AND default_branch_oid IS NOT NULL
  AND (last_indexed_oid IS NULL OR last_indexed_oid <> default_branch_oid)
ORDER BY id
LIMIT $1
`

type ListReposNeedingReindexRow struct {
	ID               int64
	Name             string
	DefaultBranch    string
	DefaultBranchOid pgtype.Text
}

// S28 code-search reconciler: returns repos whose default_branch_oid
// has advanced past last_indexed_oid (or last_indexed_oid is NULL
// and a default exists). Limited so a single tick of the cron
// doesn't try to re-index the whole world.
func (q *Queries) ListReposNeedingReindex(ctx context.Context, db DBTX, limit int32) ([]ListReposNeedingReindexRow, error) {
	rows, err := db.Query(ctx, listReposNeedingReindex, limit)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []ListReposNeedingReindexRow{}
	for rows.Next() {
		var i ListReposNeedingReindexRow
		if err := rows.Scan(
			&i.ID,
			&i.Name,
			&i.DefaultBranch,
			&i.DefaultBranchOid,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

const lockRepoOwnerName = `-- name: LockRepoOwnerName :exec
SELECT pg_advisory_xact_lock(hashtextextended($1, 0))
`

// Serializes DB + filesystem operations for one logical owner/name
// pair. Create, soft-delete, restore, and hard-delete all touch the
// canonical bare path; a transaction-scoped advisory lock keeps those
// cross-resource moves from racing.
func (q *Queries) LockRepoOwnerName(ctx context.Context, db DBTX, hashtextextended string) error {
	_, err := db.Exec(ctx, lockRepoOwnerName, hashtextextended)
	return err
}

const replaceRepoTopics = `-- name: ReplaceRepoTopics :exec
DELETE FROM repo_topics WHERE repo_id = $1
`

// Atomic full-replace: callers compose the new topic set in Go,
// then replace the existing rows in one tx (DELETE + INSERT). The
// caller's tx wraps both calls for atomicity.
func (q *Queries) ReplaceRepoTopics(ctx context.Context, db DBTX, repoID int64) error {
	_, err := db.Exec(ctx, replaceRepoTopics, repoID)
	return err
}

